std::string
ProcessorShadowSnapshotKey (const std::string &source_id, int turn)
{
  return source_id + "#" + std::to_string (turn);
}

using ProcessorShadowSnapshotMap
    = std::unordered_map<std::string, std::vector<ChronologicalStmItem>>;

struct ProcessorShadowBoundarySnapshot
{
  cortext::BoundaryDiagnostics diagnostics;
  std::string boundary_type;
};

using ProcessorShadowBoundarySnapshotMap
    = std::unordered_map<std::string, ProcessorShadowBoundarySnapshot>;

class CaptureProcessorShadowStmBefore : public cortext::IOperation
{
public:
  explicit CaptureProcessorShadowStmBefore (
      ProcessorShadowSnapshotMap *snapshots,
      ProcessorShadowBoundarySnapshotMap *boundary_snapshots = nullptr)
      : snapshots_ (snapshots),
        boundary_snapshots_ (boundary_snapshots)
  {
  }

  void
  Execute (cortext::OperationContext &context,
           cortext::Transaction &tx) const override
  {
    (void)tx;
    if (snapshots_ == nullptr)
      {
        return;
      }
    const auto &signal = context.GetSignal ();
    const int turn = signal.timestamp == 0
                         ? 0
                         : static_cast<int> (signal.timestamp / 1000ULL) - 1;
    const auto &processor = context.GetProcessorContext ();
    const auto found = processor.shadow_short_term_memory.find (
        signal.source_id);
    std::vector<ChronologicalStmItem> items;
    if (found != processor.shadow_short_term_memory.end ())
      {
        items.reserve (found->second.size ());
        const auto colon = signal.source_id.find (':');
        const std::string dataset = colon == std::string::npos
                                        ? signal.source_id
                                        : signal.source_id.substr (0, colon);
        const std::string conversation_id
            = colon == std::string::npos
                  ? std::string ()
                  : signal.source_id.substr (colon + 1);
        for (const auto &entry : found->second)
          {
            ChronologicalStmItem item;
            item.source_id = signal.source_id;
            item.dataset = dataset;
            item.conversation_id = conversation_id;
            item.turn_index = entry.timestamp == 0
                                  ? entry.step_index
                                  : static_cast<int> (entry.timestamp / 1000ULL)
                                        - 1;
            item.item_id = signal.source_id + "_turn_"
                           + std::to_string (item.turn_index);
            item.embedding = entry.embedding;
            item.boundary_score = entry.boundary_score;
            item.boundary_diagnostics = entry.boundary_diagnostics;
            item.boundary_type = entry.boundary_type.value_or ("");
            items.push_back (std::move (item));
          }
      }
    (*snapshots_)[ProcessorShadowSnapshotKey (signal.source_id, turn)]
        = std::move (items);
    if (boundary_snapshots_ != nullptr)
      {
        ProcessorShadowBoundarySnapshot snapshot;
        snapshot.diagnostics = context.GetBoundaryDiagnostics ().value_or (
            cortext::BoundaryDiagnostics{});
        snapshot.boundary_type = context.GetBoundaryType ().value_or ("");
        (*boundary_snapshots_)[ProcessorShadowSnapshotKey (signal.source_id,
                                                           turn)]
            = std::move (snapshot);
      }
  }

private:
  ProcessorShadowSnapshotMap *snapshots_ = nullptr;
  ProcessorShadowBoundarySnapshotMap *boundary_snapshots_ = nullptr;
};

