  double subject_update_threshold = 0.52;
  double event_update_threshold = 0.50;
  double subject_commit_threshold = 0.58;
  double event_commit_threshold = 0.54;
  double update_margin_threshold = 0.0;
  double commit_margin_threshold = 0.0;
